argv:
$ncm = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.InterfaceDescription -match 'NCM' }
$ncm | Select-Object Name,ifIndex,Status,MacAddress,InterfaceDescription | Format-List
foreach ($a in $ncm) {
  Get-NetIPAddress -InterfaceIndex $a.ifIndex -ErrorAction SilentlyContinue | Select-Object IPAddress,PrefixLength,AddressState,InterfaceIndex | Format-List
  Get-NetNeighbor -InterfaceIndex $a.ifIndex -ErrorAction SilentlyContinue | Select-Object IPAddress,LinkLayerAddress,State,InterfaceIndex | Format-List
  Get-NetRoute -InterfaceIndex $a.ifIndex -ErrorAction SilentlyContinue | Select-Object DestinationPrefix,NextHop,RouteMetric,InterfaceIndex | Format-List
}
